package br.uninter.baozistore.model; import jakarta.persistence.*; @Entity public class Pedido{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long clienteId; private Long produtoId; private Integer quantidade; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getClienteId(){return clienteId;} public void setClienteId(Long x){this.clienteId=x;} public Long getProdutoId(){return produtoId;} public void setProdutoId(Long x){this.produtoId=x;} public Integer getQuantidade(){return quantidade;} public void setQuantidade(Integer q){this.quantidade=q;}}